use resourcefs_core::ReadAcquisitionLimits;
use std::{
    hint::black_box,
    time::{Duration, Instant},
};

fn main() {
    let operator = ReadAcquisitionLimits::new(
        Some(7),
        Some(Duration::from_secs(12)),
        Some(4096),
        Some(8192),
        Some(8192),
    )
    .expect("valid operator");
    let start = Instant::now();
    let mut checksum = 0usize;
    for index in 0..100_000usize {
        let candidate = ReadAcquisitionLimits::new(
            Some(black_box(index % 10 + 1)),
            Some(Duration::from_nanos(black_box(index as u64 + 1))),
            Some(black_box(index % 8192 + 1)),
            Some(black_box(index % 16384 + 1)),
            Some(black_box(index % 16384 + 1)),
        )
        .expect("valid independently bounded inputs");
        let effective = black_box(candidate.intersect(operator));
        checksum = checksum.wrapping_add(effective.max_attempts());
    }
    let elapsed = start.elapsed();
    println!(
        "operations=100000 checksum={} elapsed_ns={} budget_ns=100000000",
        black_box(checksum),
        elapsed.as_nanos()
    );
    assert!(
        elapsed <= Duration::from_millis(100),
        "scalar policy exceeded the approved budget"
    );
}
